# TLS Record Layer Constants
TLS_RECORD_HEADER_LEN = 5
TLS_CONTENT_TYPE_HANDSHAKE = 22
TLS_CONTENT_TYPE_ALERT = 21
TLS_VERSION_1_2 = 0x0303  # TLS 1.2 version used for legacy_version in TLS 1.3
TLS_VERSION_1_3 = 0x0304

# Handshake Message Types
HANDSHAKE_CLIENT_HELLO = 1
HANDSHAKE_SERVER_HELLO = 2
HANDSHAKE_HELLO_RETRY_REQUEST = 6
HANDSHAKE_ENCRYPTED_EXTENSIONS = 8
HANDSHAKE_CERTIFICATE = 11
HANDSHAKE_CERTIFICATE_VERIFY = 13
HANDSHAKE_FINISHED = 14

# Extension Types
EXT_SUPPORTED_VERSIONS = 43
EXT_COOKIE = 44
EXT_KEY_SHARE = 51
EXT_PSK_KEY_EXCHANGE_MODES = 45
EXT_SIGNATURE_ALGORITHMS = 13
EXT_ALPN = 16
EXT_SCT_LIST = 18
EXT_STATUS_REQUEST = 5
EXT_USE_SRTP = 12
EXT_EC_POINT_FORMATS = 10
EXT_SESSION_TICKET = 35
EXT_RENEGOTIATION_INFO = 0xff01
EXT_EXTENDED_MASTER_SECRET = 23

# Cipher Suites
TLS_AES_128_GCM_SHA256 = 0x1301
TLS_AES_256_GCM_SHA384 = 0x1302
TLS_CHACHA20_POLY1305_SHA256 = 0x1303

# Key Share Groups
GROUP_SECP256R1 = 0x0017
GROUP_X25519 = 0x0019

def build_tls_record(content_type, version, data):
    """Constructs a TLS record layer packet."""
    header = struct.pack('!BBH', content_type, (version >> 8) & 0xff, version & 0xff, len(data))
    return header + data

def build_handshake_message(msg_type, data):
    """Constructs a TLS handshake message with length."""
    header = struct.pack('!BBB', msg_type, (len(data) >> 16) & 0xff, (len(data) >> 8) & 0xff, len(data) & 0xff)
    return header + data

def build_client_hello():
    """Constructs a minimal TLS 1.3 ClientHello message."""
    random_bytes = os.urandom(32)
    session_id = os.urandom(32)
    
    # Supported Versions Extension
    supported_versions_ext = struct.pack('!BH', 1, EXT_SUPPORTED_VERSIONS) + struct.pack('!B', 3) + struct.pack('!H', TLS_VERSION_1_3)
    
    # Key Share Extension (X25519)
    key_share_data = struct.pack('!HB', GROUP_X25519, 32) + os.urandom(32)
    key_share_ext = struct.pack('!BH', 1, EXT_KEY_SHARE) + struct.pack('!H', len(key_share_data)) + key_share_data
    
    # PSK Key Exchange Modes Extension
    psk_modes_data = struct.pack('!B', 1)  # psk_ke
    psk_modes_ext = struct.pack('!BH', 1, EXT_PSK_KEY_EXCHANGE_MODES) + struct.pack('!B', 1) + psk_modes_data
    
    # Signature Algorithms Extension
    sig_algs_data = struct.pack('!H', 0x0804)  # ecdsa_secp256r1_sha256
    sig_algs_ext = struct.pack('!BH', 1, EXT_SIGNATURE_ALGORITHMS) + struct.pack('!H', 2) + sig_algs_data
    
    extensions = supported_versions_ext + key_share_ext + psk_modes_ext + sig_algs_ext
    
    # ClientHello Body
    client_hello_body = struct.pack('!H', TLS_VERSION_1_2)  # legacy_version
    client_hello_body += random_bytes  # random
    client_hello_body += struct.pack('!B', len(session_id)) + session_id  # legacy_session_id
    client_hello_body += struct.pack('!H', 1) + struct.pack('!H', TLS_AES_128_GCM_SHA256)  # cipher_suites
    client_hello_body += struct.pack('!B', 0)  # legacy_compression_methods
    client_hello_body += struct.pack('!H', len(extensions)) + extensions  # extensions
    
    return build_handshake_message(HANDSHAKE_CLIENT_HELLO, client_hello_body)

def build_malicious_hrr(client_hello):
    """Constructs a malicious HelloRetryRequest that mimics the ClientHello but with a cookie."""
    # Extract fields from ClientHello to ensure consistency
    legacy_version = struct.unpack('!H', client_hello[0:2])[0]
    random_bytes = client_hello[2:34]
    session_id_len = client_hello[34]
    session_id = client_hello[35:35+session_id_len]
    cipher_suites_len = struct.unpack('!H', client_hello[35+session_id_len:37])[0]
    cipher_suites = client_hello[37:37+cipher_suites_len]
    compression_methods_len = client_hello[37+cipher_suites_len]
    compression_methods = client_hello[38+cipher_suites_len:38+cipher_suites_len+compression_methods_len]
    
    # Supported Versions Extension
    supported_versions_ext = struct.pack('!BH', 1, EXT_SUPPORTED_VERSIONS) + struct.pack('!B', 3) + struct.pack('!H', TLS_VERSION_1_3)
    
    # Cookie Extension (Malicious: empty or invalid cookie)
    cookie_data = b'\x00' * 32  # Empty cookie
    cookie_ext = struct.pack('!BH', 1, EXT_COOKIE) + struct.pack('!H', len(cookie_data)) + cookie_data
    
    extensions = supported_versions_ext + cookie_ext
    
    # HelloRetryRequest Body (same format as ServerHello)
    hrr_body = struct.pack('!H', TLS_VERSION_1_2)  # legacy_version
    hrr_body += random_bytes  # random
    hrr_body += struct.pack('!B', len(session_id)) + session_id  # legacy_session_id_echo
    hrr_body += struct.pack('!H', 1) + struct.pack('!H', TLS_AES_128_GCM_SHA256)  # cipher_suite
    hrr_body += struct.pack('!B', 0)  # legacy_compression_method
    hrr_body += struct.pack('!H', len(extensions)) + extensions  # extensions
    
    return build_handshake_message(HANDSHAKE_HELLO_RETRY_REQUEST, hrr_body)

def send_and_receive(sock, data):
    """Sends data over the socket and receives the response."""
    sock.sendall(data)
    response = b''
    while True:
        header = sock.recv(TLS_RECORD_HEADER_LEN)
        if not header:
            break
        content_type, version, length = struct.unpack('!BBH', header)
        body = sock.recv(length)
        response += header + body
        if content_type != TLS_CONTENT_TYPE_HANDSHAKE:
            break
    return response

